// Each node points at a parent. Follow the chain up and you
// reach the group's representative. Same representative means
// same group, which means adding an edge would close a cycle.

struct Edge { std::string from, to; int weight; };

struct UnionFind {
    std::map<std::string, std::string> parent;

    explicit UnionFind(const std::vector<std::string>& nodes) {
        for (const std::string& n : nodes) parent[n] = n;
    }

    std::string find(std::string x) {
        while (parent[x] != x) x = parent[x];
        return x;
    }

    // Not named "union" - that is a reserved keyword in C++.
    void unite(const std::string& a, const std::string& b) {
        parent[find(a)] = find(b);
    }
};

std::vector<Edge> kruskal(const std::vector<std::string>& nodes, std::vector<Edge> edges) {
    UnionFind uf(nodes);
    std::sort(edges.begin(), edges.end(),
              [](const Edge& a, const Edge& b) { return a.weight < b.weight; });

    std::vector<Edge> tree;
    for (const Edge& e : edges) {
        if (uf.find(e.from) == uf.find(e.to)) continue;  // cycle, skip
        uf.unite(e.from, e.to);
        tree.push_back(e);
        if (tree.size() == nodes.size() - 1) break;      // done early
    }
    return tree;
}

