#include <set>
#include <string>
#include <vector>

struct Edge { std::string to; int weight; };
struct TreeEdge { std::string from, to; int weight; };

std::vector<TreeEdge> prim(
    const std::map<std::string, std::vector<Edge>>& adj,
    const std::vector<std::string>& nodes,
    const std::string& start) {
    std::set<std::string> inTree{start};
    std::vector<TreeEdge> tree;

    while (inTree.size() < nodes.size()) {
        TreeEdge best{};
        bool found = false;

        for (const std::string& from : inTree) {
            auto it = adj.find(from);
            if (it == adj.end()) continue;

            for (const Edge& e : it->second) {
                if (inTree.count(e.to)) continue;          // stays inside, ignore
                if (!found || e.weight < best.weight) {
                    best = {from, e.to, e.weight};
                    found = true;
                }
            }
        }

        if (!found) break;  // graph is disconnected, cannot span it
        inTree.insert(best.to);
        tree.push_back(best);
    }
    return tree;
}
